function loadPlan(){ P=lget("lf.ulm.plan", null); if(!P || !P.pts) P={ pts:[], ac:{ tas:150, burn:15, fuel:60 }, alt:2500, dep:"" }; if(!P.ac) P.ac={ tas:150, burn:15, fuel:60 }; if(!P.alt) P.alt=2500; }
