  h+='<tr class="tot"><td>'+esc(T("Total"))+'</td><td></td><td></td><td></td><td>'+R.d.toFixed(1)+' NM</td><td></td><td></td><td>'+fDur(R.t)+'</td><td>'+R.f.toFixed(1)+' L</td></tr></table></div>';
  var need=R.f+(+P.ac.burn||0)*0.5, have=+P.ac.fuel||0, arr=new Date(+dep+R.t*60000), last=pts[pts.length-1], sun=A.sunTimes?A.sunTimes(last.lat,last.lon,arr):null, night=sun?new Date(+sun.set+18e5):null;
  h+='<div class="nv-sum"><div><b>'+R.d.toFixed(0)+'<small> NM</small></b><span>'+esc(T("Distance"))+" · "+Math.round(R.d*1.852)+' km</span></div><div><b>'+fDur(R.t)+'</b><span>'+esc(T("Durée de vol"))+'</span></div><div><b>'+need.toFixed(0)+'<small> L</small></b><span>'+esc(T("Carburant nécessaire"))+'</span></div></div>';
  var far=(+dep-Date.now())>14*864e5;
  h+='<div class="nv-dep" style="flex-wrap:wrap"><span style="width:100%">🛫 '+esc(T("Départ"))+'</span><input type="date" id="nvDate" min="'+ymd(new Date())+'" value="'+ymd(dep)+'"><input type="time" id="nvDep" value="'+esc(P.dep||hm(new Date()))+'"></div>'
    +'<div class="nv-dep" style="margin-top:6px"><span>🛬 '+esc(T("Arrivée estimée"))+'</span><b>'+(ymd(arr)!==ymd(new Date())?dmy(arr)+" · ":"")+hm(arr)+'</b></div>'
